/* =================================================================
   NAND design tokens. Every value derives from Obsidian variables (or the
   active NAND theme preset, which sets those variables), so community themes
   and presets flow through every NAND surface.
   ================================================================= */
body {
	/* Spacing: 4px grid */
	--nand-space-1: 4px;
	--nand-space-2: 8px;
	--nand-space-3: 12px;
	--nand-space-4: 16px;
	--nand-space-5: 20px;
	--nand-space-6: 24px;
	--nand-space-7: 32px;
	--nand-space-8: 40px;

	/* Radius: controls 6, cards and popovers 8, dialogs 12 */
	--nand-radius-xs: 4px;
	--nand-radius-sm: 6px;
	--nand-radius-md: 8px;
	--nand-radius-lg: 12px;
	--nand-radius-pill: 999px;

	/* Surfaces */
	--nand-surface: var(--background-primary);
	--nand-surface-muted: var(--background-secondary);
	--nand-surface-hover: var(--background-modifier-hover);
	--nand-surface-active: var(--background-modifier-active-hover);
	--nand-border-color: var(--background-modifier-border);
	--nand-border-color-strong: var(--background-modifier-border-hover);
	--nand-border: 1px solid var(--nand-border-color);

	/* Accent tints: selection, active rows, soft badges */
	--nand-accent: var(--interactive-accent);
	--nand-accent-soft: color-mix(in srgb, var(--interactive-accent) 14%, transparent);
	--nand-accent-softer: color-mix(in srgb, var(--interactive-accent) 7%, transparent);
	--nand-accent-border: color-mix(in srgb, var(--interactive-accent) 50%, transparent);
	--nand-focus-ring: 0 0 0 2px color-mix(in srgb, var(--interactive-accent) 45%, transparent);

	/* Semantic tones: used only for their meaning */
	--nand-tone-success: var(--color-green);
	--nand-tone-warning: var(--color-orange);
	--nand-tone-error: var(--color-red);
	--nand-tone-info: var(--color-blue);

	/* Elevation */
	--nand-shadow-xs: 0 1px 2px rgba(0, 0, 0, 0.05);
	--nand-shadow-sm: var(--shadow-s);
	--nand-shadow-md: 0 4px 16px rgba(0, 0, 0, 0.12);
	--nand-shadow-lg: var(--shadow-l);

	/* Layers (never above 50; Obsidian's own modals and menus sit above) */
	--nand-z-base: 0;
	--nand-z-sticky: 10;
	--nand-z-overlay: 20;
	--nand-z-popover: 30;
	--nand-z-modal: 40;
	--nand-z-toast: 50;

	/* Motion */
	--nand-ease: cubic-bezier(0.2, 0, 0, 1);
	--nand-duration-fast: 120ms;
	--nand-duration: 180ms;
	--nand-duration-slow: 240ms;

	/* Controls */
	--nand-control-height: 32px;
	--nand-control-height-sm: 28px;
	--nand-control-height-lg: 36px;
	--nand-touch-target: 44px;
	--nand-icon-size: 16px;

	/* Type */
	--nand-text-caption: var(--font-ui-smaller);
	--nand-text-body: var(--font-ui-small);
	--nand-text-title: var(--font-ui-medium);
	--nand-text-heading: var(--font-ui-large);

	/* Workbench shell */
	--nand-rail-width: 52px;
	--nand-panel-width: 260px;
	--nand-header-height: 44px;
	--nand-list-row-height: 32px;
}

/* ----- Card: one resting surface; interactive cards lift one tier ----- */
.nand-ui-card {
	box-sizing: border-box;
	padding: var(--size-4-4);
	background: var(--nand-surface);
	border: var(--nand-border);
	border-radius: var(--nand-radius-md);
	box-shadow: var(--nand-shadow-xs);
}
.nand-ui-card.is-interactive,
button.nand-ui-card {
	cursor: pointer;
	transition: border-color var(--nand-duration) var(--nand-ease), box-shadow var(--nand-duration) var(--nand-ease), background-color var(--nand-duration) var(--nand-ease);
}
.nand-ui-card.is-interactive:hover,
button.nand-ui-card:hover {
	border-color: var(--nand-border-color-strong);
	box-shadow: var(--nand-shadow-sm);
}
.nand-ui-card.is-selected {
	border-color: var(--nand-accent-border);
	background: var(--nand-accent-softer);
}
.nand-ui-panel-muted {
	background: var(--nand-surface-muted);
}

/* ----- Layout helpers ----- */
.nand-ui-toolbar {
	display: flex;
	flex-wrap: wrap;
	align-items: center;
	gap: var(--size-4-2);
	min-width: 0;
}
.nand-ui-spacer { flex: 1 1 auto; }
.nand-ui-stack {
	display: flex;
	flex-direction: column;
	gap: var(--size-4-2);
	min-width: 0;
}
.nand-ui-divider {
	height: 1px;
	margin: var(--size-4-2) 0;
	border: 0;
	background: var(--nand-border-color);
}

/* ----- Buttons ----- */
button.nand-ui-btn {
	display: inline-flex;
	align-items: center;
	justify-content: center;
	gap: 6px;
	min-height: var(--nand-control-height);
	padding: 0 var(--size-4-3);
	border-radius: var(--nand-radius-sm);
	white-space: nowrap;
}
button.nand-ui-btn svg { width: 15px; height: 15px; flex: none; }
button.nand-ui-btn-ghost {
	background: transparent;
	box-shadow: none;
	border: none;
	color: var(--text-muted);
}
button.nand-ui-btn-ghost:hover:not(:disabled) {
	background: var(--nand-surface-hover);
	color: var(--text-normal);
}
button.nand-ui-icon-btn {
	display: inline-flex;
	align-items: center;
	justify-content: center;
	flex: none;
	width: var(--nand-control-height);
	height: var(--nand-control-height);
	min-width: var(--nand-control-height);
	padding: 0;
	border: none;
	border-radius: var(--nand-radius-sm);
	background: transparent;
	box-shadow: none;
	color: var(--text-muted);
	transition: background-color var(--nand-duration-fast) var(--nand-ease), color var(--nand-duration-fast) var(--nand-ease);
}
button.nand-ui-icon-btn:hover:not(:disabled) {
	background: var(--nand-surface-hover);
	color: var(--text-normal);
}
button.nand-ui-icon-btn.is-active {
	background: var(--nand-accent-soft);
	color: var(--text-accent);
}
button.nand-ui-icon-btn:disabled { opacity: 0.4; cursor: default; }
button.nand-ui-icon-btn svg { width: 16px; height: 16px; }
button.nand-ui-icon-btn > span { display: flex; }

/* ----- Segmented control: a group of aria-pressed buttons ----- */
.nand-ui-segmented {
	display: inline-flex;
	align-items: center;
	gap: 2px;
	padding: 2px;
	border: var(--nand-border);
	border-radius: calc(var(--nand-radius-sm) + 2px);
	background: var(--nand-surface-muted);
}
.nand-ui-segmented > button {
	min-height: calc(var(--nand-control-height) - 6px);
	padding: 0 var(--size-4-3);
	border: none;
	border-radius: var(--nand-radius-sm);
	background: transparent;
	box-shadow: none;
	color: var(--text-muted);
	font-size: var(--nand-text-body);
	font-weight: 500;
	transition: background-color var(--nand-duration-fast) var(--nand-ease), color var(--nand-duration-fast) var(--nand-ease);
}
.nand-ui-segmented > button:hover:not([aria-pressed="true"]):not(.is-active) {
	background: var(--nand-surface-hover);
	color: var(--text-normal);
}
.nand-ui-segmented > button[aria-pressed="true"],
.nand-ui-segmented > button.is-active {
	background: var(--nand-surface);
	color: var(--text-normal);
	box-shadow: var(--nand-shadow-xs);
	font-weight: 600;
}

/* ----- Form field: caption label above a control ----- */
.nand-ui-field {
	display: flex;
	flex-direction: column;
	gap: var(--size-4-1);
	min-width: 0;
}
.nand-ui-field > span:first-child {
	color: var(--text-muted);
	font-size: var(--nand-text-caption);
	font-weight: 500;
}
.nand-ui-field :is(input, select) {
	min-width: 0;
	max-width: 100%;
	border-radius: var(--nand-radius-sm);
}

/* ----- Badge / status chip ----- */
.nand-ui-badge {
	display: inline-flex;
	align-items: center;
	gap: 4px;
	min-height: 20px;
	padding: 0 8px;
	border-radius: var(--nand-radius-pill);
	background: var(--nand-surface-muted);
	color: var(--text-muted);
	font-size: var(--nand-text-caption);
	font-weight: 500;
	line-height: 20px;
	white-space: nowrap;
	vertical-align: middle;
}
.nand-ui-badge--accent { background: var(--nand-accent-soft); color: var(--text-accent); }
.nand-ui-badge--success { background: color-mix(in srgb, var(--nand-tone-success) 15%, transparent); color: var(--nand-tone-success); }
.nand-ui-badge--warning { background: color-mix(in srgb, var(--nand-tone-warning) 15%, transparent); color: var(--nand-tone-warning); }
.nand-ui-badge--error { background: color-mix(in srgb, var(--nand-tone-error) 15%, transparent); color: var(--nand-tone-error); }
.nand-ui-badge--info { background: color-mix(in srgb, var(--nand-tone-info) 15%, transparent); color: var(--nand-tone-info); }
.nand-ui-dot {
	display: inline-block;
	flex: none;
	width: 7px;
	height: 7px;
	border-radius: 50%;
	background: currentColor;
}

/* ----- List rows: selectable navigation items ----- */
.nand-ui-list {
	display: flex;
	flex-direction: column;
	gap: 2px;
	min-width: 0;
}
button.nand-ui-list-item {
	display: flex;
	flex-direction: column;
	align-items: stretch;
	gap: 2px;
	width: 100%;
	height: auto;
	min-height: 0;
	padding: var(--size-4-2) 10px;
	border: 1px solid transparent;
	border-radius: var(--nand-radius-sm);
	background: transparent;
	box-shadow: none;
	color: var(--text-normal);
	font-weight: 400;
	text-align: start;
	white-space: normal;
	transition: background-color var(--nand-duration-fast) var(--nand-ease), border-color var(--nand-duration-fast) var(--nand-ease);
}
button.nand-ui-list-item:hover { background: var(--nand-surface-hover); }
button.nand-ui-list-item.is-active {
	background: var(--nand-accent-soft);
	border-color: var(--nand-accent-border);
}
.nand-ui-list-item-title {
	min-width: 0;
	overflow: hidden;
	color: var(--text-normal);
	font-size: var(--nand-text-body);
	font-weight: 600;
	text-overflow: ellipsis;
}
.nand-ui-list-item-meta {
	min-width: 0;
	color: var(--text-muted);
	font-size: var(--nand-text-caption);
}

/* ----- Section label: small heading above a group ----- */
.nand-ui-section-label {
	margin: var(--size-4-3) 0 var(--size-4-1);
	color: var(--text-faint);
	font-size: var(--nand-text-caption);
	font-weight: 600;
	letter-spacing: 0.04em;
	text-transform: uppercase;
}

/* ----- Scroll container ----- */
.nand-ui-scroll {
	min-height: 0;
	overflow: auto;
	scrollbar-width: thin;
	scrollbar-gutter: stable;
}

:where(.nand-ui-card, .nand-ui-segmented, .nand-ui-list, .nand-ui-toolbar) :focus-visible,
:where(button.nand-ui-icon-btn, button.nand-ui-btn, button.nand-ui-list-item, button.nand-ui-card):focus-visible {
	outline: 2px solid var(--interactive-accent);
	outline-offset: 2px;
}
@media (pointer: coarse) {
	button.nand-ui-icon-btn { width: var(--nand-touch-target); height: var(--nand-touch-target); min-width: var(--nand-touch-target); }
	button.nand-ui-btn, .nand-ui-segmented > button { min-height: var(--nand-touch-target); }
}
@media (prefers-reduced-motion: reduce) {
	:is(.nand-ui-card, button.nand-ui-icon-btn, button.nand-ui-list-item, .nand-ui-segmented > button) { transition: none; }
}

/* =================================================================
   Dashboard Plugin — Multi-Theme Design System
   ================================================================= */

/* =================================================================
   Primitive controls (src/ui/primitives). Sizes follow the token scale;
   colors come only from tokens.
   ================================================================= */

/* ----- Buttons ----- */
button.nand-btn {
	display: inline-flex;
	align-items: center;
	justify-content: center;
	gap: var(--nand-space-2);
	height: var(--nand-control-height);
	padding: 0 var(--nand-space-3);
	border: 1px solid var(--nand-border-color);
	border-radius: var(--nand-radius-sm);
	background: var(--nand-surface);
	box-shadow: none;
	color: var(--text-normal);
	font-size: var(--nand-text-body);
	font-weight: var(--font-medium);
	white-space: nowrap;
	cursor: pointer;
	transition: background-color var(--nand-duration-fast) var(--nand-ease), border-color var(--nand-duration-fast) var(--nand-ease), color var(--nand-duration-fast) var(--nand-ease);
}
button.nand-btn:hover:not(:disabled) { background: var(--nand-surface-hover); border-color: var(--nand-border-color-strong); }
button.nand-btn:focus-visible { box-shadow: var(--nand-focus-ring); outline: none; }
button.nand-btn:disabled { opacity: 0.5; cursor: default; }
button.nand-btn svg { width: var(--nand-icon-size); height: var(--nand-icon-size); flex: none; }
button.nand-btn--sm { height: var(--nand-control-height-sm); padding: 0 var(--nand-space-2); font-size: var(--nand-text-caption); }
button.nand-btn--primary { background: var(--interactive-accent); border-color: transparent; color: var(--text-on-accent); }
button.nand-btn--primary:hover:not(:disabled) { background: var(--interactive-accent-hover); border-color: transparent; }
button.nand-btn--ghost { background: transparent; border-color: transparent; color: var(--text-muted); }
button.nand-btn--ghost:hover:not(:disabled) { background: var(--nand-surface-hover); border-color: transparent; color: var(--text-normal); }
button.nand-btn--danger { color: var(--nand-tone-error); }
button.nand-btn--danger:hover:not(:disabled) { background: color-mix(in srgb, var(--nand-tone-error) 10%, transparent); border-color: color-mix(in srgb, var(--nand-tone-error) 40%, transparent); }

button.nand-icon-btn {
	display: inline-flex;
	align-items: center;
	justify-content: center;
	flex: none;
	width: var(--nand-control-height);
	height: var(--nand-control-height);
	padding: 0;
	border: none;
	border-radius: var(--nand-radius-sm);
	background: transparent;
	box-shadow: none;
	color: var(--text-muted);
	cursor: pointer;
	transition: background-color var(--nand-duration-fast) var(--nand-ease), color var(--nand-duration-fast) var(--nand-ease);
}
button.nand-icon-btn:hover:not(:disabled) { background: var(--nand-surface-hover); color: var(--text-normal); }
button.nand-icon-btn:focus-visible { box-shadow: var(--nand-focus-ring); outline: none; }
button.nand-icon-btn.is-active,
button.nand-icon-btn[aria-pressed="true"] { background: var(--nand-surface-active); color: var(--text-normal); }
button.nand-icon-btn:disabled { opacity: 0.4; cursor: default; }
button.nand-icon-btn--sm { width: var(--nand-control-height-sm); height: var(--nand-control-height-sm); }
button.nand-icon-btn svg { width: var(--nand-icon-size); height: var(--nand-icon-size); }

/* ----- Text fields ----- */
.nand-field {
	display: flex;
	flex-direction: column;
	gap: var(--nand-space-1);
	min-width: 0;
}
.nand-field-label { color: var(--text-muted); font-size: var(--nand-text-caption); font-weight: var(--font-medium); }
.nand-field-hint { color: var(--text-faint); font-size: var(--nand-text-caption); }
input.nand-input,
textarea.nand-input,
select.nand-input {
	width: 100%;
	min-height: var(--nand-control-height);
	padding: 0 var(--nand-space-3);
	border: 1px solid var(--nand-border-color);
	border-radius: var(--nand-radius-sm);
	background: var(--background-modifier-form-field);
	color: var(--text-normal);
	font-size: var(--nand-text-body);
}
textarea.nand-input { padding: var(--nand-space-2) var(--nand-space-3); line-height: 1.5; resize: vertical; }
input.nand-input:focus,
textarea.nand-input:focus,
select.nand-input:focus { border-color: var(--interactive-accent); box-shadow: var(--nand-focus-ring); outline: none; }

.nand-search {
	position: relative;
	display: flex;
	align-items: center;
	min-width: 0;
}
.nand-search-icon {
	position: absolute;
	inset-inline-start: var(--nand-space-2);
	display: flex;
	color: var(--text-faint);
	pointer-events: none;
}
.nand-search-icon svg { width: 14px; height: 14px; }
.nand-search input.nand-input { padding-inline-start: calc(var(--nand-space-2) + 20px); }

/* ----- Tabs (pill tabs inside a page) ----- */
.nand-tabs {
	display: inline-flex;
	gap: 2px;
	padding: 2px;
	border-radius: var(--nand-radius-md);
	background: var(--nand-surface-muted);
}
.nand-tabs > button {
	height: var(--nand-control-height-sm);
	padding: 0 var(--nand-space-3);
	border: none;
	border-radius: var(--nand-radius-sm);
	background: transparent;
	box-shadow: none;
	color: var(--text-muted);
	font-size: var(--nand-text-body);
	cursor: pointer;
}
.nand-tabs > button:hover:not([aria-selected="true"]) { color: var(--text-normal); }
.nand-tabs > button[aria-selected="true"] { background: var(--nand-surface); box-shadow: var(--nand-shadow-xs); color: var(--text-normal); font-weight: var(--font-medium); }
.nand-tabs > button:focus-visible { box-shadow: var(--nand-focus-ring); outline: none; }

/* ----- Badge ----- */
.nand-badge {
	display: inline-flex;
	align-items: center;
	gap: var(--nand-space-1);
	min-width: 18px;
	height: 18px;
	padding: 0 6px;
	border-radius: var(--nand-radius-pill);
	background: var(--nand-surface-muted);
	color: var(--text-muted);
	font-size: 11px;
	font-weight: var(--font-semibold);
	line-height: 1;
	justify-content: center;
}
.nand-badge--accent { background: var(--interactive-accent); color: var(--text-on-accent); }
.nand-badge--error { background: var(--nand-tone-error); color: var(--text-on-accent); }
.nand-badge--success { background: color-mix(in srgb, var(--nand-tone-success) 16%, transparent); color: var(--nand-tone-success); }
.nand-badge--warning { background: color-mix(in srgb, var(--nand-tone-warning) 16%, transparent); color: var(--nand-tone-warning); }

/* ----- List rows (side panel, list-detail) ----- */
.nand-list { display: flex; flex-direction: column; gap: 1px; margin: 0; padding: 0; list-style: none; }
.nand-list-item {
	position: relative;
	display: flex;
	align-items: center;
	gap: var(--nand-space-2);
	min-height: var(--nand-list-row-height);
	padding: 0 var(--nand-space-2);
	border-radius: var(--nand-radius-md);
	color: var(--text-normal);
	font-size: var(--nand-text-body);
	cursor: pointer;
	user-select: none;
}
.nand-list-item:hover { background: var(--nand-surface-hover); }
.nand-list-item:focus-visible { box-shadow: var(--nand-focus-ring); outline: none; }
.nand-list-item.is-active { background: var(--nand-surface-active); font-weight: var(--font-medium); }
.nand-list-item-icon { display: flex; flex: none; color: var(--text-muted); }
.nand-list-item-icon svg { width: var(--nand-icon-size); height: var(--nand-icon-size); }
.nand-list-item-label { flex: 1 1 auto; min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.nand-list-item-meta { flex: none; color: var(--text-faint); font-size: var(--nand-text-caption); }
.nand-list-item-actions { display: none; flex: none; }
.nand-list-item:hover .nand-list-item-actions,
.nand-list-item:focus-within .nand-list-item-actions,
.nand-list-item.is-active .nand-list-item-actions { display: flex; }
.nand-list-item:hover .nand-list-item-meta,
.nand-list-item:focus-within .nand-list-item-meta { display: none; }
.nand-list-section-title {
	padding: var(--nand-space-3) var(--nand-space-2) var(--nand-space-1);
	color: var(--text-faint);
	font-size: var(--nand-text-caption);
	font-weight: var(--font-semibold);
}

/* ----- Skeleton (loading placeholder) ----- */
.nand-skeleton {
	border-radius: var(--nand-radius-sm);
	background: linear-gradient(90deg, var(--nand-surface-muted) 25%, var(--nand-surface-hover) 50%, var(--nand-surface-muted) 75%);
	background-size: 200% 100%;
	animation: nand-skeleton 1.2s ease-in-out infinite;
}
@keyframes nand-skeleton {
	from { background-position: 200% 0; }
	to { background-position: -200% 0; }
}

/* ----- Dialog body (Obsidian Modal hosting a Preact view) ----- */
.nand-dialog .modal-content { padding: 0; }
.nand-dialog-body { display: flex; flex-direction: column; gap: var(--nand-space-4); padding: var(--nand-space-4) var(--nand-space-5); }
.nand-dialog-footer { display: flex; justify-content: flex-end; gap: var(--nand-space-2); padding: var(--nand-space-3) var(--nand-space-5) var(--nand-space-4); border-top: var(--nand-border); }

@media (prefers-reduced-motion: reduce) {
	.nand-skeleton { animation: none; }
	button.nand-btn,
	button.nand-icon-btn,
	.nand-list-item { transition: none; }
}
@media (pointer: coarse) {
	button.nand-btn,
	button.nand-icon-btn,
	input.nand-input,
	select.nand-input { min-height: var(--nand-touch-target); }
	button.nand-icon-btn { min-width: var(--nand-touch-target); }
	.nand-list-item { min-height: var(--nand-touch-target); }
}

/* Screen-reader-only text (also used to label containers without `aria-label`, which Obsidian turns into hover tooltips). */
.nand-visually-hidden {
	position: absolute;
	width: 1px;
	height: 1px;
	overflow: hidden;
	clip-path: inset(50%);
	white-space: nowrap;
}
.nand-content-page {
	display: flex;
	flex-direction: column;
	gap: var(--nand-space-3);
	min-width: 0;
	min-height: 0;
	height: 100%;
	padding: var(--nand-space-4);
	overflow: auto;
}

.nand-content-status {
	margin: 0;
	color: var(--text-muted);
	overflow-wrap: anywhere;
}

.nand-content-body {
	flex: 1;
	min-height: 240px;
	min-width: 0;
	overflow: auto;
	overflow-wrap: anywhere;
}

.nand-content-editor {
	width: 100%;
	height: 100%;
	min-height: 240px;
	resize: vertical;
	font-family: var(--font-monospace);
	line-height: 1.6;
}

.nand-content-attachment {
	max-width: 100%;
	max-height: 100%;
	object-fit: contain;
}

.nand-content-page iframe.nand-content-attachment {
	width: 100%;
	flex: 1;
	min-height: 320px;
	border: var(--nand-border);
}

.nand-content-results {
	display: flex;
	flex-direction: column;
	gap: var(--nand-space-2);
}

.nand-content-results button {
	justify-content: flex-start;
	white-space: normal;
	overflow-wrap: anywhere;
	text-align: start;
}
