.nand-contacts-person-text .nand-contacts-muted { font-size: var(--nand-text-caption); }
.nand-contacts-person-text .nand-contacts-muted:empty { display: none; }

/* Pagination: compact centered pill. */
.nand-contacts-pagination { display: flex; align-items: center; justify-content: center; gap: var(--size-4-2); width: fit-content; max-width: 100%; margin: var(--size-4-4) auto 0; padding: 2px; border: var(--nand-border); border-radius: var(--nand-radius-pill); background: var(--nand-surface-muted); flex-wrap: wrap; }
.nand-contacts-pagination > span { padding: 0 var(--size-4-2); color: var(--text-muted); font-size: var(--nand-text-caption); font-variant-numeric: tabular-nums; }
.nand-contacts-pagination button.nand-ui-btn { min-height: var(--nand-control-height-sm); padding: 0 var(--size-4-2); border-radius: var(--nand-radius-pill); font-size: var(--nand-text-caption); }
.nand-contacts-pagination button.nand-ui-btn svg { width: 14px; height: 14px; }
.nand-contacts-pagination button.nand-ui-btn > span { display: flex; }
.nand-contacts-pagination button.nand-ui-btn:disabled { opacity: 0.4; }

/* Empty, loading, error states. */
.nand-contacts-empty { display: flex; flex-direction: column; align-items: center; justify-content: center; gap: var(--size-4-3); min-height: 200px; padding: 48px var(--size-4-4); border: 1px dashed var(--nand-border-color); border-radius: var(--nand-radius-md); background: var(--nand-accent-softer); color: var(--text-muted); font-size: var(--nand-text-body); text-align: center; }
.nand-contacts-empty p { max-width: 36ch; margin: 0; }
.nand-contacts-empty-icon { display: flex; align-items: center; justify-content: center; width: 48px; height: 48px; border-radius: 50%; background: var(--nand-accent-soft); color: var(--text-accent); }
.nand-contacts-empty-icon svg { width: 24px; height: 24px; }
.nand-contacts-status { display: flex; align-items: center; justify-content: center; min-height: 96px; margin: 0; color: var(--text-muted); text-align: center; }
.nand-contacts-error { color: var(--text-error); overflow-wrap: anywhere; }
.nand-contacts-banner { display: flex; align-items: center; flex-wrap: wrap; gap: var(--size-4-2); margin-bottom: var(--size-4-3); padding: var(--size-4-2) var(--size-4-3); border: 1px solid color-mix(in srgb, var(--nand-tone-error) 35%, transparent); border-radius: var(--nand-radius-sm); background: color-mix(in srgb, var(--nand-tone-error) 8%, transparent); font-size: var(--nand-text-body); }
.nand-contacts-detail > .nand-contacts-banner { margin-bottom: 0; }
.nand-contacts-banner > span:not(.nand-contacts-banner-icon) { flex: 1 1 auto; min-width: 0; }
.nand-contacts-banner-icon { display: flex; flex: none; }
.nand-contacts-banner-icon svg { width: 16px; height: 16px; }
.nand-contacts-surface button.nand-contacts-clear { margin-bottom: var(--size-4-3); }
.nand-contacts-surface button.nand-contacts-clear > span { display: flex; }
.nand-contacts-surface button.nand-contacts-clear svg { width: 14px; height: 14px; }
.nand-contacts-markdown { font-size: var(--nand-text-body); }
.nand-contacts-markdown > div > :first-child { margin-top: 0; }
.nand-contacts-markdown > div > :last-child { margin-bottom: 0; }
/* Obsidian 1.13 pads every .setting-item-heading by --size-4-4 on both sides
   so it lines up with a settings card. This modal's option rows are not in a
   settings card, so that padding puts group titles 16px to the right of the
   options. Reset only this modal. */
.modal.nand-contacts-filter .setting-item.setting-item-heading {
	padding-left: 0;
	padding-right: 0;
	padding-inline: 0;
}
/* The record form: inline in the archives page, or in a dialog when creating a company from another form. */
.nand-contacts-editor-page { max-width: 760px; margin: 0 auto; padding: var(--size-4-4) var(--size-4-6) var(--size-4-8); }
.nand-contacts-form-title { margin: 0 0 var(--size-4-3); font-size: var(--nand-text-heading); font-weight: var(--font-semibold); }
.modal.nand-contacts-form-dialog { width: min(640px, calc(100vw - var(--size-4-8))); max-height: 90vh; }
.nand-contacts-form-dialog .modal-content { display: flex; flex-direction: column; min-height: 0; overflow: hidden; }
.nand-contacts-form-body { min-height: 0; overflow-y: auto; padding-inline-end: var(--size-4-2); }
.nand-contacts-form .setting-item:not(.setting-item-heading), .nand-contacts-form .setting-item-heading { align-items: stretch; flex-direction: column; gap: var(--size-4-1); padding: 0; margin: 0 0 var(--size-4-3); border: 0; }
.nand-contacts-form .setting-item-info { margin-inline-end: 0; }
.nand-contacts-form .setting-item-name { font-size: var(--nand-text-body); }
.nand-contacts-form .setting-item-control { width: 100%; justify-content: flex-start; flex-wrap: wrap; }
.nand-contacts-form input:not([type="checkbox"]), .nand-contacts-form textarea { width: 100%; min-width: 0; border-radius: var(--nand-radius-sm); }
.nand-contacts-form textarea { min-height: 72px; max-height: 240px; overflow-y: auto; resize: vertical; }
.nand-contacts-form-group + .nand-contacts-form-group { margin-top: var(--size-4-6); }
.nand-contacts-form .setting-item-heading .setting-item-name { font-weight: 600; }
.nand-contacts-multi { width: 100%; text-align: start; }
.nand-contacts-value-row { display: flex; gap: var(--size-4-2); align-items: center; margin-bottom: var(--size-4-1); }
.nand-contacts-value-row input { flex: 1; }
.nand-contacts-value-row button { flex: none; }
.nand-contacts-chips { display: flex; flex-wrap: wrap; gap: var(--size-4-1); }
.nand-contacts-chips:not(:empty) { margin-bottom: var(--size-4-2); }
.nand-contacts-value-chip { gap: var(--size-4-1); overflow-wrap: anywhere; }
.nand-contacts-value-chip button { background: transparent; box-shadow: none; padding: 0 var(--size-4-1); color: var(--text-muted); }
.nand-contacts-form-footer { flex: none; padding-top: var(--size-4-3); border-top: var(--nand-border); }
.nand-contacts-form .nand-contacts-form-footer .setting-item { margin: 0; }
.nand-contacts-form-footer .setting-item-control { justify-content: flex-end; }
.nand-contacts-field-error, .nand-contacts-form-body > .nand-contacts-error { color: var(--text-error); font-size: var(--nand-text-caption); }
.nand-contacts-field-error:empty { display: none; }
.nand-contacts-form-body > .nand-contacts-error:not(:empty) { margin-bottom: var(--size-4-2); }
.nand-contacts-form input[aria-invalid="true"] { border-color: var(--text-error); }
.is-mobile .nand-contacts-form button, .is-mobile .nand-contacts-form input, .is-mobile .nand-contacts-form select { min-height: var(--nand-touch-target); }
.is-mobile .nand-contacts-form button { min-width: var(--nand-touch-target); }

/* Phone and touch. */
.nand-contacts-phone .nand-contacts-header-actions { display: none; }
.nand-contacts-phone .nand-contacts-grid { grid-template-columns: 1fr; }
.nand-contacts-phone .nand-contacts-surface { padding: var(--size-4-3) var(--size-4-3) calc(var(--size-4-4) + var(--nand-contacts-navbar-height, var(--mobile-navbar-height, 64px))); }
.nand-contacts-phone button { min-height: 44px; min-width: 44px; }
.nand-contacts-phone .nand-contacts-surface button.nand-contacts-action { width: 44px; height: 44px; }
.nand-contacts-phone .nand-contacts-grid button.nand-contacts-card { min-height: 0; }
.nand-contacts-phone .nand-contacts-search input[type="search"] { min-height: 44px; }
@media (pointer: coarse) {
 .nand-contacts-surface button.nand-contacts-action { width: 44px; height: 44px; min-width: 44px; }
 .nand-contacts-pagination button.nand-ui-btn { min-height: 44px; }
}
@media (prefers-reduced-motion: reduce) {
 .nand-contacts-grid button.nand-contacts-card, .nand-contacts-people button.nand-contacts-person { transition: none; }
 .nand-contacts-grid button.nand-contacts-card:hover { transform: none; }
}
@media (max-width: 600px) {
 .nand-contacts-search { flex-basis: 100%; order: 3; }
 .nand-contacts-profile { flex-wrap: wrap; gap: var(--size-4-3); }
 .nand-contacts-form .setting-item { flex-direction: column; gap: var(--size-4-2); }
 .nand-contacts-form .setting-item-control { width: 100%; flex-wrap: wrap; }
 .nand-contacts-form input, .nand-contacts-form textarea { width: 100%; min-width: 0; }
 .nand-contacts-entry { flex-wrap: wrap; }
}

/* Notification inbox page: a toolbar and the list of notification rows (width limited like other reading pages). */
.nand-inbox-page { height: 100%; overflow-y: auto; padding: var(--nand-space-4) var(--nand-space-6); }
.nand-inbox { display: flex; flex-direction: column; gap: var(--size-4-3); min-width: 0; max-width: 960px; margin-inline: auto; }
.nand-inbox-header { display: flex; flex-wrap: wrap; align-items: center; justify-content: flex-end; gap: var(--size-4-2); padding-bottom: var(--size-4-3); border-bottom: var(--nand-border); }
.nand-inbox-actions { gap: var(--size-4-1); }
.nand-inbox .nand-empty-state-description:empty { display: none; }
.nand-inbox-list { display: flex; flex-direction: column; gap: var(--size-4-2); margin: 0; padding: 0; list-style: none; }
.nand-inbox-item { display: grid; grid-template-columns: 8px minmax(0, 1fr) auto; align-items: start; gap: var(--size-4-3); margin: 0; padding: var(--size-4-3); border: var(--nand-border); border-radius: var(--nand-radius-md); background: var(--nand-surface); transition: border-color var(--nand-duration) var(--nand-ease), box-shadow var(--nand-duration) var(--nand-ease); }
.nand-inbox-item:hover { border-color: var(--nand-border-color-strong); box-shadow: var(--nand-shadow-sm); }
.nand-inbox-item.is-unread { border-color: var(--nand-accent-border); background: var(--nand-accent-softer); }
.nand-inbox-dot { width: 8px; height: 8px; margin-top: 6px; border-radius: 50%; background: transparent; }
.nand-inbox-item.is-unread .nand-inbox-dot { background: var(--nand-accent); }
.nand-inbox-item-main { display: flex; flex-direction: column; gap: var(--size-4-1); min-width: 0; }
.nand-inbox-item-title { color: var(--text-normal); font-size: var(--nand-text-body); font-weight: 600; line-height: 1.4; overflow-wrap: anywhere; }
.nand-inbox-item.is-read .nand-inbox-item-title { font-weight: 500; }
.nand-inbox-item-body { color: var(--text-muted); font-size: var(--nand-text-body); line-height: 1.5; overflow-wrap: anywhere; }
.nand-inbox-item-meta { display: flex; flex-wrap: wrap; align-items: center; gap: var(--size-4-1) var(--size-4-2); margin-top: 2px; color: var(--text-muted); font-size: var(--nand-text-caption); }
.nand-inbox-item-time { display: inline-flex; align-items: center; gap: 4px; font-variant-numeric: tabular-nums; }
.nand-inbox-meta-icon { display: flex; color: var(--text-faint); }
.nand-inbox-meta-icon svg { width: 12px; height: 12px; }
.nand-inbox-item-actions { display: flex; flex-wrap: wrap; justify-content: flex-end; gap: var(--size-4-1); }
.nand-inbox-item-actions button.nand-ui-btn { min-height: var(--nand-control-height-sm); padding: 0 var(--size-4-2); font-size: var(--nand-text-caption); }
@media (max-width: 480px) {
 .nand-inbox-item { grid-template-columns: 8px minmax(0, 1fr); }
 .nand-inbox-item-actions { grid-column: 2; justify-content: flex-start; }
}
@media (pointer: coarse) {
 .nand-inbox button.nand-ui-btn, .nand-inbox-item-actions button.nand-ui-btn { min-height: var(--nand-touch-target); }
}
@media (prefers-reduced-motion: reduce) {
 .nand-inbox-item { transition: none; }
}
/* Git sync page: summary, commit box, file groups with inline diffs, history; conflict buttons in the editor. */
.nand-sync-page { height: 100%; overflow-y: auto; padding: var(--nand-space-4) var(--nand-space-6); }
.nand-sync-body { display: flex; flex-direction: column; gap: var(--nand-space-4); min-width: 0; max-width: 960px; margin-inline: auto; }
.nand-sync-muted { color: var(--text-muted); font-size: var(--nand-text-caption); }
.nand-sync-summary { display: flex; flex-direction: column; gap: var(--nand-space-2); padding-bottom: var(--nand-space-3); border-bottom: var(--nand-border); }
.nand-sync-branch { display: flex; flex-wrap: wrap; align-items: baseline; gap: var(--nand-space-2); }
.nand-sync-branch-name { font-size: var(--nand-text-title); font-weight: 600; overflow-wrap: anywhere; }
.nand-sync-last { color: var(--text-normal); font-size: var(--nand-text-body); }
.nand-sync-last.is-error { color: var(--nand-tone-error); }
.nand-sync-detail { margin: 0; padding: var(--nand-space-2) var(--nand-space-3); border-radius: var(--nand-radius-sm); background: var(--nand-surface-muted); color: var(--text-muted); font-size: var(--nand-text-caption); white-space: pre-wrap; overflow-wrap: anywhere; }
.nand-sync-banner { display: flex; flex-wrap: wrap; align-items: center; justify-content: space-between; gap: var(--nand-space-2); padding: var(--nand-space-2) var(--nand-space-3); border: var(--nand-border); border-radius: var(--nand-radius-md); background: var(--nand-surface-muted); font-size: var(--nand-text-body); }
.nand-sync-banner.is-error { border-color: var(--nand-tone-error); }
.nand-sync-conflict p { margin: var(--nand-space-1) 0 0; color: var(--text-muted); }
.nand-sync-actions { display: flex; flex-wrap: wrap; align-items: center; gap: var(--nand-space-2); }
.nand-sync-spacer { flex: 1 1 auto; }
.nand-sync-changes { display: flex; flex-direction: column; gap: var(--nand-space-4); }
.nand-sync-commit { display: flex; flex-direction: column; gap: var(--nand-space-2); }
.nand-sync-message { width: 100%; min-height: calc(var(--nand-control-height) * 2); resize: vertical; font-size: var(--nand-text-body); }
.nand-sync-clean { margin: 0; }
.nand-sync-group { display: flex; flex-direction: column; gap: var(--nand-space-1); }
.nand-sync-group-header { display: flex; align-items: center; gap: var(--nand-space-2); }
.nand-sync-group-header h3 { margin: 0; font-size: var(--nand-text-body); font-weight: 600; }
.nand-sync-count { padding: 0 var(--nand-space-2); border-radius: var(--nand-radius-pill); background: var(--nand-surface-muted); color: var(--text-muted); font-size: var(--nand-text-caption); }
.nand-sync-files { display: flex; flex-direction: column; margin: 0; padding: 0; list-style: none; }
.nand-sync-file { border-radius: var(--nand-radius-sm); }
.nand-sync-file-row { display: flex; align-items: center; gap: var(--nand-space-2); min-height: var(--nand-control-height); padding: 0 var(--nand-space-1); border-radius: var(--nand-radius-sm); }
.nand-sync-file-row:hover { background: var(--nand-surface-hover); }
.nand-sync-code { flex: 0 0 auto; min-width: 1.6em; color: var(--text-muted); font-family: var(--font-monospace); font-size: var(--nand-text-caption); text-align: center; }
.nand-sync-code.is-A, .nand-sync-code.is-U { color: var(--nand-tone-success); }
.nand-sync-code.is-D { color: var(--nand-tone-error); }
.nand-sync-file.is-conflict .nand-sync-code { color: var(--nand-tone-error); }
.nand-sync-file-row button.nand-sync-file-name { display: block; flex: 1 1 auto; min-width: 0; height: auto; overflow: hidden; padding: 2px 0; border: 0; background: transparent; box-shadow: none; color: var(--text-normal); font-size: var(--nand-text-body); text-align: start; text-overflow: ellipsis; white-space: nowrap; cursor: pointer; }
.nand-sync-file-row button.nand-sync-file-name:focus-visible { box-shadow: var(--nand-focus-ring); }
.nand-sync-file-actions { display: flex; flex: 0 0 auto; gap: var(--nand-space-1); opacity: 0.6; }
.nand-sync-file-row:hover .nand-sync-file-actions, .nand-sync-file-row:focus-within .nand-sync-file-actions { opacity: 1; }
.nand-sync-diff { max-height: 420px; margin: var(--nand-space-1) 0 var(--nand-space-2); padding: var(--nand-space-2) var(--nand-space-3); overflow: auto; border-radius: var(--nand-radius-sm); background: var(--nand-surface-muted); font-family: var(--font-monospace); font-size: var(--nand-text-caption); white-space: pre; }
.nand-sync-diff .is-add { color: var(--nand-tone-success); }
.nand-sync-diff .is-del { color: var(--nand-tone-error); }
.nand-sync-diff .is-hunk { color: var(--nand-tone-info); }
.nand-sync-setup { align-items: center; text-align: center; }
.nand-sync-clone { width: 100%; text-align: start; overflow-wrap: anywhere; }
.nand-sync-clone summary { min-height: var(--nand-control-height); padding-block: var(--nand-space-2); cursor: pointer; }
.nand-sync-clone summary:focus-visible { box-shadow: var(--nand-focus-ring); }
.nand-sync-clone-form { display: flex; flex-direction: column; gap: var(--nand-space-2); }
.nand-sync-check { display: inline-flex; align-items: center; gap: var(--nand-space-2); font-size: var(--nand-text-body); }
.nand-sync-history { display: flex; flex-direction: column; gap: var(--nand-space-2); }
.nand-sync-commits { display: flex; flex-direction: column; margin: 0; padding: 0; list-style: none; }
.nand-sync-commits button.nand-sync-commit-row { display: flex; flex-direction: column; align-items: flex-start; gap: 2px; width: 100%; height: auto; padding: var(--nand-space-2); border: 0; border-radius: var(--nand-radius-sm); background: none; box-shadow: none; text-align: start; cursor: pointer; }
.nand-sync-commits button.nand-sync-commit-row:hover { background: var(--nand-surface-hover); }
.nand-sync-commit-subject { color: var(--text-normal); font-size: var(--nand-text-body); overflow-wrap: anywhere; white-space: normal; }
.nand-sync-dialog-text { white-space: pre-wrap; overflow-wrap: anywhere; }
.nand-sync-conflict-actions { display: inline-flex; flex-wrap: wrap; gap: var(--nand-space-1); margin-inline-start: var(--nand-space-2); vertical-align: middle; }
.nand-sync-conflict-button { height: auto; padding: 0 var(--nand-space-2); font-family: var(--font-interface); font-size: var(--nand-text-caption); }
@media (max-width: 600px) {
 .nand-sync-page { padding: var(--nand-space-3); }
 .nand-sync-file-actions { opacity: 1; }
}
@media (pointer: coarse) {
 .nand-sync-file-row { min-height: var(--nand-touch-target); }
}
/* Retained browser guests stay in one parent across workspace layout changes. */
.nand-browser-retained-root {
	display: contents;
}
.nand-browser-retained-host {
	position: fixed;
	top: 0;
	left: -10000px;
	width: 1px;
	height: 1px;
	overflow: hidden;
	pointer-events: none;
}
.nand-browser-retained-host .nand-browser-webview {
	display: flex;
	width: 100%;
	height: 100%;
}
.nand-browser-toolbar .nand-browser-tool {
	min-width: 32px;
	min-height: 32px;
}
.nand-browser-markup-canvas {
	overflow: auto;
	min-height: 0;
	flex: 1;
}
.nand-browser-markup-canvas canvas {
	max-width: 100%;
	touch-action: none;
}

.nand-browser-retained-host.is-visible {
	left: var(--browser-left);
	pointer-events: auto;
}
/* Host boundary and legacy embedded pages; removed as module pages migrate. */
.workspace-leaf-content[data-type="nand-workbench-view"] > .view-content { padding: 0; overflow: hidden; }
body:not(.is-mobile) .workspace-leaf-content[data-type="nand-workbench-view"] > .view-header { display: none; }
.nand-workbench-page[hidden], .nand-workbench-context[hidden], .nand-workbench-context-page[hidden] { display: none; }
.nand-workbench-context:empty { display: none; }
.nand-workbench-agent-objects { height: 100%; box-sizing: border-box; gap: var(--size-4-2); }
.nand-workbench-agent-objects:empty { display: none; }
.nand-automation-run-history { padding: var(--size-4-4); height: 100%; }
.nand-automation-run.is-selected { background: var(--nand-accent-soft); border-radius: var(--nand-radius-sm); }
.nand-automation-run:focus-visible { outline: 2px solid var(--interactive-accent); outline-offset: 2px; }

.nand-workbench-home-overview { display: grid; grid-template-columns: minmax(0, 1fr) minmax(0, 2fr); gap: var(--size-4-4); padding: var(--size-4-4); }
.nand-workbench-home-calendar, .nand-workbench-home-recent { min-width: 0; border: 1px solid var(--db-border); border-radius: var(--db-radius-md); padding: var(--size-4-3); }
.nand-workbench-home-recent .dashboard-recent { margin: 0; }
/* Stacked layout hides these classes in the sidebar. The home overview is the place they stay visible. */
.nand-workbench-home-overview .nand-workbench-home-calendar .dashboard-sidebar-week-calendar { display: flex; }
.nand-workbench-home-overview .nand-workbench-home-recent .dashboard-recent { display: block; }
@container (max-width: 560px) { .nand-workbench-home-overview { grid-template-columns: 1fr; } }
